        private void RefreshDesktop(string desktopPath, string lnkPath)
        {
            // 1) 带真实路径通知 Shell：桌面目录内容已变化 → 重新读取，新快捷方式立即出现
            IntPtr pDesk = Marshal.StringToHGlobalUni(desktopPath);
            SHChangeNotify(0x00001000 /*SHCNE_UPDATEDIR*/, 0x0001 /*SHCNF_PATH*/ | 0x1000 /*SHCNF_FLUSH*/, pDesk, IntPtr.Zero);
            Marshal.FreeHGlobal(pDesk);
            // 2) 通知 Shell：新建了一个快捷方式条目
            if (!string.IsNullOrEmpty(lnkPath))
            {
                IntPtr pLnk = Marshal.StringToHGlobalUni(lnkPath);
                SHChangeNotify(0x00000002 /*SHCNE_CREATE*/, 0x0001 /*SHCNF_PATH*/ | 0x1000 /*SHCNF_FLUSH*/, pLnk, IntPtr.Zero);
                Marshal.FreeHGlobal(pLnk);
            }
            // 3) 图标关联变化（让 .lnk 重新解析目标 exe 的图标）
            SHChangeNotify(0x08000000 /*SHCNE_ASSOCCHANGED*/, 0x0000 /*SHCNF_IDLIST*/, IntPtr.Zero, IntPtr.Zero);
            // 4) 兼容兜底：ie4uinit 重建/刷新 Shell 图标缓存（静默，无弹窗）
            try { System.Diagnostics.Process.Start("ie4uinit.exe", "-show"); } catch { }
            // 5) 再兜底：激活桌面并刷新视图
            try
            {
                Type shellType = Type.GetTypeFromProgID("WScript.Shell");
                dynamic shell = Activator.CreateInstance(shellType);
                shell.AppActivate("Program Manager");
                System.Threading.Thread.Sleep(150);
                shell.SendKeys("{F5}");
            }
            catch { }
        }

        private void Cleanup()
        {
            if (tempZip != null && File.Exists(tempZip))
            {
                try { File.Delete(tempZip); } catch { }
                tempZip = null;
            }
        }

        private void btnInstall_Click(object sender, EventArgs e)
        {
            string installPath = txtPath.TextValue.Trim();
            if (string.IsNullOrEmpty(installPath)) { MessageBox.Show("请选择安装位置！"); return; }

            lblTitle.Visible = false;
            lblInfo.Visible = false;
            lblPath.Visible = false;
            txtPath.Visible = false;
            btnBrowse.Visible = false;
            btnInstall.Visible = false;
            btnCancel.Visible = false;
            panelProgress.Visible = true;
            panelProgress.BringToFront();

            try
            {
                UpdateProgress(5, "正在准备安装包...");
                tempZip = Path.Combine(Path.GetTempPath(), "AI_manju_setup_" + new Random().Next() + ".zip");
                byte[] zipBytes = Convert.FromBase64String(ZipBase64);
                File.WriteAllBytes(tempZip, zipBytes);
                UpdateProgress(10, "安装包准备完成");

                System.Collections.Generic.List<string> fileList = new System.Collections.Generic.List<string>();
                using (ZipArchive zip = ZipFile.OpenRead(tempZip))
                {
                    foreach (ZipArchiveEntry entry in zip.Entries)
                    {
                        if (entry.Length > 0) fileList.Add(entry.Name);
                    }
                }
                int totalFiles = fileList.Count;

                UpdateProgress(15, "正在解压文件...");
                if (!Directory.Exists(installPath)) Directory.CreateDirectory(installPath);
                string appDir = Path.Combine(installPath, "AI系列生产工具");
                if (Directory.Exists(appDir)) Directory.Delete(appDir, true);
                ZipFile.ExtractToDirectory(tempZip, installPath);

                for (int i = 0; i < totalFiles; i++)
                {
                    int percent = 15 + (int)((i + 1) / (double)totalFiles * 75);
                    UpdateProgress(percent, "正在解压: " + fileList[i]);
                    System.Threading.Thread.Sleep(150);
                }

                UpdateProgress(92, "正在创建桌面快捷方式...");
                string desktopPath = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
                string lnkPath = Path.Combine(desktopPath, "AI系列生产工具.lnk");
                string exePath = Path.Combine(appDir, "AI Series Production Tool 3.2.0.65.exe");
                bool shortcutCreated = false;
                try
                {
                    if (File.Exists(lnkPath)) File.Delete(lnkPath);
                    Type shellType = Type.GetTypeFromProgID("WScript.Shell");
                    dynamic shell = Activator.CreateInstance(shellType);
                    dynamic shortcut = shell.CreateShortcut(lnkPath);
                    shortcut.TargetPath = exePath;
                    shortcut.WorkingDirectory = appDir;
                    shortcut.Description = "AI系列生产工具";
                    shortcut.Save();
                    System.Threading.Thread.Sleep(300);
                    shortcutCreated = File.Exists(lnkPath);
                }
                catch { }

                installedExe = exePath;
                if (File.Exists(exePath))
                {
                    UpdateProgress(100, "");
                    RefreshDesktop(desktopPath, lnkPath);
                    ShowCompleted(appDir);
                }
                else
                {
                    Cleanup();
                    MessageBox.Show("安装失败，未找到程序文件。", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    this.Close();
                }
            }
            catch (Exception ex)
            {
                Cleanup();
                MessageBox.Show("安装失败：" + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                this.Close();
            }
        }
    }

    class GradientButton : Control
    {
        public Color C1 = Color.FromArgb(108, 140, 245);
        public Color C2 = Color.FromArgb(150, 118, 255);
        public bool Flat = false;
        bool hover, pressed;

        public GradientButton()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
            Cursor = Cursors.Hand;
            Font = new Font("微软雅黑", 9.5F, FontStyle.Bold);
            ForeColor = Color.White;
        }
        protected override void OnMouseEnter(EventArgs e) { hover = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseDown(MouseEventArgs e) { pressed = true; Invalidate(); base.OnMouseDown(e); }
        protected override void OnMouseUp(MouseEventArgs e) { pressed = false; Invalidate(); base.OnMouseUp(e); }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
            Rectangle rc = new Rectangle(0, 0, Width - 1, Height - 1);
            using (GraphicsPath p = Shape.RoundRect(rc, 9))
            {
                if (Flat)
                {
                    Color bg = hover ? Color.FromArgb(231, 237, 251) : Color.FromArgb(241, 244, 250);
                    using (SolidBrush b = new SolidBrush(bg)) g.FillPath(b, p);
                    using (Pen pen = new Pen(Color.FromArgb(226, 231, 242))) g.DrawPath(pen, p);
                    TextRenderer.DrawText(g, Text, Font, rc, Color.FromArgb(59, 66, 87), TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
                }
                else
                {
                    Color c1 = C1, c2 = C2;
                    if (hover) { c1 = ControlPaint.Light(C1, 0.1f); c2 = ControlPaint.Light(C2, 0.1f); }
                    if (pressed) { c1 = ControlPaint.Dark(C1, 0.1f); c2 = ControlPaint.Dark(C2, 0.1f); }
                    using (LinearGradientBrush b = new LinearGradientBrush(rc, c1, c2, 35f)) g.FillPath(b, p);
                    TextRenderer.DrawText(g, Text, Font, rc, Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
                }
            }
        }
    }

    class GradientBar : Control
    {
        public int Maximum = 100;
        int _value;
        public int Value { get { return _value; } set { _value = Math.Max(0, Math.Min(Maximum, value)); Invalidate(); } }

        public GradientBar()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
        }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Rectangle rc = new Rectangle(0, 0, Width - 1, Height - 1);
            using (GraphicsPath p = Shape.RoundRect(rc, Height / 2))
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(242, 244, 252))) g.FillPath(b, p);
                double f = Maximum > 0 ? (double)Value / Maximum : 0;
                if (f > 0)
                {
                    int w = Math.Max(Height, (int)(rc.Width * f));
                    Rectangle frc = new Rectangle(0, 0, w, Height - 1);
                    using (GraphicsPath fp = Shape.RoundRect(frc, Height / 2))
                    using (LinearGradientBrush gb = new LinearGradientBrush(frc, Color.FromArgb(108, 140, 245), Color.FromArgb(150, 118, 255), 0f))
                        g.FillPath(gb, fp);
                }
                using (Pen pen = new Pen(Color.FromArgb(226, 231, 242))) g.DrawPath(pen, p);
            }
        }
    }
}
